bool CheckPermutation(char *s1, char *s2) {
  int n1 = strlen(s1), n2 = strlen(s2);
  if (n1 != n2) return false;
  int count[128] = {0};
  for (int i = 0; i < n1; i++) {
    count[(unsigned char)s1[i]]++;
    count[(unsigned char)s2[i]]--;
  }
  for (int i = 0; i < 128; i++) {
    if (count[i]) return false;
  }
  return true;
}

